package jp.terada.midnitelogger;
import android.app.*; import android.content.*; import android.os.*; import java.util.concurrent.*;
public class LoggerService extends Service {private ScheduledExecutorService ex;private Database db;
 public void onCreate(){super.onCreate();db=new Database(this);foreground();getSharedPreferences(Config.PREFS,0).edit().putBoolean("running",true).apply();db.event("INFO","Service開始");ex=Executors.newSingleThreadScheduledExecutor();ex.scheduleWithFixedDelay(new Runnable(){public void run(){cycle();}},0,Config.LOG_INTERVAL_MS,TimeUnit.MILLISECONDS);}
 private void cycle(){try{ClassicReader r=new ClassicReader(new Modbus.L(){public void log(String l,String m){db.event(l,m);}});Record x=r.read();db.insert(x);db.event("DATA","Battery="+x.batteryV+"V PV="+x.pvV+"V Power="+x.watts+"W");db.purgeEvents();}catch(Exception e){db.event("ERROR",e.getClass().getSimpleName()+": "+e.getMessage());}}
 private void foreground(){if(Build.VERSION.SDK_INT>=26){NotificationManager n=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);n.createNotificationChannel(new NotificationChannel("logger","MidNite Logger",NotificationManager.IMPORTANCE_LOW));}PendingIntent pi=PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class),Build.VERSION.SDK_INT>=23?PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE:PendingIntent.FLAG_UPDATE_CURRENT);Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(this,"logger"):new Notification.Builder(this);startForeground(1,b.setSmallIcon(android.R.drawable.stat_notify_sync).setContentTitle("MidNite Logger").setContentText("Classicロギング中").setContentIntent(pi).setOngoing(true).build());}
 public int onStartCommand(Intent i,int f,int id){return START_STICKY;}public void onDestroy(){if(ex!=null)ex.shutdownNow();if(db!=null)db.event("INFO","Service停止");getSharedPreferences(Config.PREFS,0).edit().putBoolean("running",false).apply();super.onDestroy();}public IBinder onBind(Intent i){return null;}}
